.apache.hadoop.hive.ql.io.SymlinkTextInputFormat'\nOUTPUTFORMAT 'org.apache.hadoop.hive.ql.io.HiveIgnoreKeyTextOutputFormat'\nLOCATION 's3://oapg100-20261109-854be6ee-502425560524/manifests/topics/'","sha256":"0fd4071986fbcb90f89a079c521fddc90663f7004b81b393f05384ba82f61359"},{"sql":"CREATE VIEW works AS SELECT try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS work_id, CASE WHEN w.publication_year BETWEEN 0 AND 65535 THEN w.publication_year END AS publication_year,\n            w.type AS work_type, coalesce(w.open_access.is_oa, false) AS is_oa,\n            coalesce(w.is_xpac, false) AS is_xpac,\n            cast(w.cited_by_count AS bigint) AS cited_by_count\n            FROM raw_works w WHERE try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL","sha256":"cf68e131870d11cdbfcb0ea8af329685bfc537853938e8b3df5e962c23701e8e"},{"sql":"CREATE VIEW authors AS SELECT try_cast(regexp_extract(id, '[A-Z]([0-9]+)$', 1) AS bigint) AS author_id, display_name\n            FROM raw_authors WHERE try_cast(regexp_extract(id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL","sha256":"c478fdf2a1bb51df92a88eb234138e0072674a474e321ce4184c6bd59b62fed2"},{"sql":"CREATE VIEW work_author AS SELECT try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS work_id, try_cast(regexp_extract(a.author.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS author_id\n            FROM raw_works w CROSS JOIN UNNEST(w.authorships) AS u(a)\n            WHERE try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL AND try_cast(regexp_extract(a.author.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL","sha256":"9c448274d80aafe662057fe524737e3b250cb9fe26e8d022136dc68215c42279"},{"sql":"CREATE VIEW work_institution AS SELECT DISTINCT try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS work_id,\n            try_cast(regexp_extract(a.author.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS author_id, try_cast(regexp_extract(i.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS institution_id\n            FROM raw_works w CROSS JOIN UNNEST(w.authorships) AS u(a)\n            CROSS JOIN UNNEST(a.institutions) AS v(i)\n            WHERE try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL AND try_cast(regexp_extract(a.author.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL\n            AND try_cast(regexp_extract(i.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL","sha256":"2f4f6c90f36f056227bd5f32b459519ed060eab0d3995648dfb415d08e384ed7"},{"sql":"CREATE VIEW institutions AS SELECT try_cast(regexp_extract(id, '[A-Z]([0-9]+)$', 1) AS bigint) AS institution_id,\n            nullif(country_code, '') AS country_code\n            FROM raw_institutions WHERE try_cast(regexp_extract(id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL","sha256":"d6d0e064f6e1984c797229911a0b83af83a805ddd638a82ae25505bbb0b0ab9d"},{"sql":"CREATE VIEW topics AS SELECT try_cast(regexp_extract(id, '[A-Z]([0-9]+)$', 1) AS bigint) AS topic_id, display_name\n            FROM raw_topics WHERE try_cast(regexp_extract(id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL\n            AND try_cast(regexp_extract(subfield.id, '/([0-9]+)$', 1) AS bigint) IS NOT NULL\n            AND try_cast(regexp_extract(field.id, '/([0-9]+)$', 1) AS bigint) IS NOT NULL\n            AND try_cast(regexp_extract(domain.id, '/([0-9]+)$', 1) AS bigint) IS NOT NULL","sha256":"08d010c0720a6e8a01e7f566959f0110b0a257206b61dc7d3e2cb752782b87fe"},{"sql":"CREATE VIEW work_topic AS SELECT try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS work_id, try_cast(regexp_extract(t.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS topic_id\n            FROM raw_works w CROSS JOIN UNNEST(w.topics) AS u(t)\n            WHERE try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL AND try_cast(regexp_extract(t.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL\n            AND t.score IS NOT NULL","sha256":"5869fba22b59427cebbcd6b6b87d0810781d0cec866808e9420b647ceb7e3e24"},{"sql":"CREATE VIEW citation_edge AS SELECT try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS citing_work_id,\n            try_cast(regexp_extract(ref, '[A-Z]([0-9]+)$', 1) AS bigint) AS cited_work_id, min(CASE WHEN w.publication_year BETWEEN 0 AND 65535 THEN w.publication_year END) AS citing_year\n            FROM raw_works w CROSS JOIN UNNEST(w.referenced_works) AS u(ref)\n            WHERE try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL AND try_cast(regexp_extract(ref, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL\n            GROUP BY try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint), try_cast(regexp_extract(ref, '[A-Z]([0-9]+)$', 1) AS bigint)","sha256":"ee08a65adaa51836e8e982969243a38785c37f542fe2953f0d60ad6b24b740d9"}]},"200m":{"id":"200m","label":"200.31m","works":200313862,"raw_bytes":341270321934,"raw_work_bytes":288201704857,"columns":42,"date":"2026-11-12","seeds":["51557542","24222542","2003585639"],"table_counts":{"works":200313862,"work_author":324997581,"work_institution":240576651,"work_topic":410939659,"citation_edge":1250072961,"authors":119129660,"institutions":127784,"sources":283287,"topics":4516},"normalized_bytes":20283651843,"core_works":127375852,"xpac_works":72938010,"note":"955 Work objects, all 480 prior 100m files preserved; 39.25% of historical 510,372,821-Work June snapshot. Wider final fields/entities not yet validated.","athena_views":[{"sql":"CREATE VIEW citation_edge AS SELECT try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS citing_work_id,\n            try_cast(regexp_extract(ref, '[A-Z]([0-9]+)$', 1) AS bigint) AS cited_work_id, min(CASE WHEN w.publication_year BETWEEN 0 AND 65535 THEN w.publication_year END) AS citing_year\n            FROM raw_works w
